  let current=sections[0];for(const section of sections)if(section.offsetTop<=top)current=section;
  if(body.scrollTop+body.clientHeight>=body.scrollHeight-4)current=sections.at(-1);
  for(const link of document.querySelectorAll('.settings-nav a')){const on=link.getAttribute('href')===`#${current.id}`;link.classList.toggle('selected',on);if(on)$('settings-crumb').textContent=link.textContent;}
