// Slash commands in the composer. Only a leading "/word" opens the menu, so
// ordinary messages that mention a path are never intercepted.
const SLASH_COMMANDS=[
  ['/new','New session',()=>createSession()],
  ['/sessions','Search sessions',()=>showPalette()],
  ['/agent','Switch agent',()=>chooseAgent()],
  ['/model','Switch model and effort',()=>chooseModel()],
  ['/effort','Cycle reasoning effort',()=>cycleReasoningEffort()],
  ['/context','Inspect the next request',()=>openContextDialog()],
  ['/details','Toggle the session panel',()=>toggleInspector()],
  ['/logs','Open daemon and session logs',()=>openLogs()],
  ['/export','Export session transcript',()=>exportCurrent('markdown')],
  ['/archive','Archive this session',()=>{const s=state.sessions.find(row=>row.id===state.session);if(s)archiveSession(s);}],
  ['/stop','Stop the running turn',()=>stopTurn()],
  ['/settings','Open settings',()=>openSettings()],
];
const slash={open:false,rows:[],selected:0};
function slashQuery(){const m=input.value.match(/^\/(\S*)$/);return m?m[1].toLowerCase():null;}
function renderSlash(){
  const query=slashQuery(),menu=$('slash-menu');
  if(query===null||input.disabled){closeSlash();return;}
  slash.rows=SLASH_COMMANDS.filter(([name,summary])=>name.slice(1).startsWith(query)||summary.toLowerCase().includes(query));
  slash.selected=Math.min(slash.selected,Math.max(0,slash.rows.length-1));slash.open=true;menu.hidden=false;menu.replaceChildren();
  slash.rows.forEach(([name,summary],i)=>{const b=el('button',`slash-item ${i===slash.selected?'selected':''}`);b.type='button';b.id=`slash-${i}`;b.setAttribute('role','option');b.setAttribute('aria-selected',String(i===slash.selected));b.tabIndex=-1;b.append(el('span','',name),el('span','',summary));b.onmousedown=e=>e.preventDefault();b.onclick=()=>runSlash(i);menu.append(b);});
  if(!slash.rows.length)menu.append(el('div','slash-empty','No matching command'));
  input.setAttribute('aria-activedescendant',slash.rows.length?`slash-${slash.selected}`:'');
  menu.querySelector('.selected')?.scrollIntoView({block:'nearest'});
}
function closeSlash(){slash.open=false;slash.selected=0;$('slash-menu').hidden=true;input.removeAttribute('aria-activedescendant');}
function runSlash(i){const row=slash.rows[i];if(!row)return;input.value='';saveDraft();closeSlash();row[2]();}
input.addEventListener('input',()=>{slash.selected=0;renderSlash();});
input.addEventListener('blur',()=>setTimeout(()=>{if(document.activeElement!==input)closeSlash();},120));
input.addEventListener('keydown',e=>{
  if(!slash.open||e.isComposing||e.keyCode===229)return;
  const n=slash.rows.length;
  if(e.key==='ArrowDown'||e.key==='ArrowUp'){if(!n)return;e.preventDefault();e.stopImmediatePropagation();slash.selected=(slash.selected+(e.key==='ArrowDown'?1:-1)+n)%n;renderSlash();}
  else if((e.key==='Enter'&&!e.shiftKey)||e.key==='Tab'){if(!n)return;e.preventDefault();e.stopImmediatePropagation();runSlash(slash.selected);}
  else if(e.key==='Escape'){e.preventDefault();e.stopImmediatePropagation();closeSlash();}
},true);
