// Enrich the shared picker after its normal setup. The current model becomes
// the initial active row, and its current effort is the provisional value.
// Make the active model/effort the picker default; Left/Right only adjust
// effort when search is empty so a populated query retains normal caret use.
const renderPickerBase=renderPalette;
renderPalette=function(query=''){
  renderPickerBase(query);
  if(state.choiceMode!=='model')return;
  const help=$('palette-results').querySelector('.effort-help');
  if(help)help.textContent=query?'Left / Right moves the search caret; clear search to adjust effort':'Left / Right adjusts effort · Enter applies';
  const effortHint=[...$('palette-footer').children].find(item=>item.textContent.includes('←')&&item.textContent.includes('→'));
  if(effortHint?.firstChild)effortHint.firstChild.textContent=query?'Search caret ':'Effort ';
};
$('palette-input').addEventListener('keydown',event=>{
  if(state.choiceMode==='model'&&(event.key==='ArrowLeft'||event.key==='ArrowRight')&&$('palette-input').value){
    event.stopImmediatePropagation();
  }
});
